#include <stdio.h>
#include <string.h>
#include "libavfilter/avfilter.h"
#include "libavutil/log.h"
static void string(const char *s){if(!s){printf("null");return;}putchar('"');for(const unsigned char *p=(const unsigned char *)s;*p;p++){if(*p=='"'||*p=='\\')putchar('\\');if(*p<32)printf("\\u%04x",*p);else putchar(*p);}putchar('"');}
static int index_of(AVFilterGraph *g,AVFilterContext *f){for(unsigned i=0;i<g->nb_filters;i++)if(g->filters[i]==f)return i;return -1;}
static void external(AVFilterGraph *g,AVFilterInOut *list){putchar('[');int comma=0;for(AVFilterInOut *io=list;io;io=io->next){if(comma++)putchar(',');printf("{\"node\":%d,\"pad\":%d,\"label\":",index_of(g,io->filter_ctx),io->pad_idx);string(io->name);putchar('}');}putchar(']');}
int main(int argc,char **argv){if(argc!=2)return 2;av_log_set_level(AV_LOG_QUIET);AVFilterGraph *graph=avfilter_graph_alloc();AVFilterInOut *inputs=NULL,*outputs=NULL;int result=avfilter_graph_parse2(graph,argv[1],&inputs,&outputs);printf("{\"accepted\":%s",result<0?"false":"true");if(result>=0){printf(",\"nodes\":[");for(unsigned i=0;i<graph->nb_filters;i++){AVFilterContext *f=graph->filters[i];if(i)putchar(',');printf("{\"name\":");string(f->filter->name);printf(",\"instanceName\":");const char *instance=strchr(f->name,'@');string(instance?instance+1:NULL);printf(",\"inputs\":%u,\"outputs\":%u,\"inputTypes\":[",f->nb_inputs,f->nb_outputs);for(unsigned p=0;p<f->nb_inputs;p++){if(p)putchar(',');string(avfilter_pad_get_type(f->input_pads,p)==AVMEDIA_TYPE_VIDEO?"video":"audio");}printf("],\"outputTypes\":[");for(unsigned p=0;p<f->nb_outputs;p++){if(p)putchar(',');string(avfilter_pad_get_type(f->output_pads,p)==AVMEDIA_TYPE_VIDEO?"video":"audio");}printf("]}");}printf("],\"edges\":[");int comma=0;for(unsigned i=0;i<graph->nb_filters;i++){AVFilterContext *f=graph->filters[i];for(unsigned j=0;j<f->nb_outputs;j++){AVFilterLink *link=f->outputs[j];if(!link)continue;int target=index_of(graph,link->dst),pad=-1;for(unsigned k=0;k<link->dst->nb_inputs;k++)if(link->dst->inputs[k]==link)pad=k;if(comma++)putchar(',');printf("{\"from\":[%u,%u],\"to\":[%d,%d]}",i,j,target,pad);}}printf("],\"inputs\":");external(graph,inputs);printf(",\"outputs\":");external(graph,outputs);}puts("}");avfilter_inout_free(&inputs);avfilter_inout_free(&outputs);avfilter_graph_free(&graph);return 0;}
